import{_ as t,c as r,o as s,ah as o}from"./chunks/framework.BssxmkiH.js";const f=JSON.parse('{"title":"Atmosphere Settings","description":"","frontmatter":{},"headers":[],"relativePath":"atmosphere-settings.md","filePath":"atmosphere-settings.md"}'),a={name:"atmosphere-settings.md"};function i(n,e,h,d,l,c){return s(),r("div",null,e[0]||(e[0]=[o('<h1 id="atmosphere-settings" tabindex="-1">Atmosphere Settings <a class="header-anchor" href="#atmosphere-settings" aria-label="Permalink to “Atmosphere Settings”">​</a></h1><p>The atmosphere settings holds settings that controls the atmosphere</p><table tabindex="0"><thead><tr><th>Property</th><th>Function</th></tr></thead><tbody><tr><td>Render Resolution</td><td>The resolution of the internal render textures used for atmosphere rendering. Lower values like <strong>128</strong> or <strong>256</strong> are fine and more performant since the atmosphere color changes gradually, increase only if needed. <br><br> This is a <a href="./glossary#static-parameters">static</a> and <a href="./glossary#performance-sensitive-parameters">performance sensitive</a> parameter.</td></tr><tr><td>Sun Disc Size</td><td>The apparent size of the sun disc.</td></tr><tr><td>Sun Bloom</td><td>The intensity of the sun&#39;s corona.</td></tr><tr><td>Planet Scale</td><td>The radius of the planet in kilometers. This affects the horizon line. This value is relative to 6371000 meters, which is the average radius of Earth.</td></tr><tr><td>Atmosphere Scale</td><td>The thickness of the atmosphere in kilometers. This affects the height of the atmosphere from the horizon line. This value is relative to 100000 meters, which is a reasonable scale for atmosphere thickness.</td></tr><tr><td>Mie Scattering</td><td>The mie scattering coefficient. This controls the size and intensity of the mist around the sun.</td></tr><tr><td>Density</td><td>The density of the atmosphere. This controls the overall intensity of the atmospheric scattering.</td></tr><tr><td>Exposure</td><td>The exposure of the atmosphere. This controls the overall brightness of the atmosphere.</td></tr><tr><td>Enable Celestials</td><td>Enables rendering of the <a href="./moon-settings">moon</a> and <a href="./star-settings">stars</a>. <br><br> This is a <a href="./glossary#static-parameters">static</a> and <a href="./glossary#performance-sensitive-parameters">performance sensitive</a> parameter.</td></tr><tr><td>Night Sky Color</td><td>The color of the sky at night. This color comes to play when the sun is below the horizon.</td></tr><tr><td>Ground Color</td><td>The color of the ground.</td></tr><tr><td>Air Density</td><td>Rayleigh atmospheric scattering coefficients for air molecules. This is responsible for the blue color of the sky and the reddening of the sun near the horizon. You can tweak these values to achieve different atmospheric colors or to simulate other planets&#39; atmospheres.</td></tr><tr><td>Ozone</td><td>Absorption coefficients for ozone. This removes specific colors from the light beam. Mostly affects the color of the sky near the horizon, especially during sunrise/sunset. You can tweak them to achieve different atmospheric colors or to simulate other planets&#39; atmospheres.</td></tr></tbody></table>',3)]))}const p=t(a,[["render",i]]);export{f as __pageData,p as default};
